 class="bact-result <?=htmlspecialchars($p['result']??'')?>"><?=$p['result']==='positive'?'POSITIVO':($p['result']==='negative'?'NEGATIVO':'—')?></span><?php endif;?></td><td><span class="bact-status <?=htmlspecialchars($p['status'])?>"><?=htmlspecialchars($poolLabels[$p['status']]??$p['status'])?></span></td><td><a class="button button-secondary button-compact" href="/quality-control/bacteriology/pools/map?ids=<?=$p['id']?>" target="_blank">Mapa</a><?php if($p['status']==='open'&&$p['result']===null&&$canPool):?><button type="button" class="button button-danger button-compact" data-cancel-pool="<?=$p['id']?>">Cancelar</button><?php endif;?></td></tr><?php endforeach;?><?php if(!$pools):?><tr><td colspan="7" class="qc-empty">Nenhum pool encontrado.</td></tr><?php endif;?></tbody></table></div></section>

