<dialog id="bact-cancel"><form method="post" action="/quality-control/bacteriology/pools/cancel"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="pool_id"><h2>Cancelar pool aberto</h2><p>O histórico será preservado e as unidades serão liberadas.</p><label><span>Motivo obrigatório</span><textarea name="reason" maxlength="500" required></textarea></label><div><button type="button" class="button button-secondary" onclick="this.closest('dialog').close()">Voltar</button><button class="button button-danger">Confirmar</button></div></form></dialog>
<script>document.querySelectorAll('[data-individual-result],[data-retest-result]').forEach(form=>{const result=form.querySelector('[name=result]'),box=form.querySelector('[data-individual-bacteria],[data-retest-bacteria]'),input=box?.querySelector('input'),isRetest=form.hasAttribute('data-retest-result');const sync=()=>{const positive=result.value==='positive';if(box)box.hidden=!positive;if(input){input.disabled=!positive;input.required=isRetest&&positive;if(!positive&&input.dataset.persisted!=='1')input.value=''}};result.addEventListener('change',sync);form.addEventListener('submit',e=>{if(input&&!isRetest){input.disabled=result.value!=='positive';input.required=e.submitter?.name==='complete'&&result.value==='positive'}});sync()});const bulk=document.querySelector('#bact-bulk-form');if(bulk)bulk.addEventListener('submit',()=>{bulk.querySelectorAll('[data-bulk-value]').forEach(el=>el.remove());document.querySelectorAll('[data-individual-result]').forEach(form=>{const id=form.dataset.sampleId;['result','identified_bacteria','notes'].forEach(name=>{const source=form.querySelector(`[name="${name}"]`),input=document.createElement('input');input.type='hidden';input.name=`samples[${id}][${name}]`;input.value=source?.value||'';input.dataset.bulkValue='1';bulk.append(input)})})});document.querySelectorAll('[data-positive-form]').forEach(form=>form.addEventListener('submit',e=>{if(e.submitter?.dataset.positiveComplete===undefined||form.querySelector('[name=result]').value!=='positive'||form.dataset.confirmed)return;e.preventDefault();const pool=form.classList.contains('bact-pool-form'),d=document.querySelector('#bact-positive');d.querySelector('p').textContent=pool?'Este pool é POSITIVO. As unidades serão encaminhadas para análise individual.':'Este resultado é POSITIVO e iniciará ou confirmará a etapa de investigação bacteriológica. Deseja continuar?';d.showModal();d.addEventListener('close',()=>{if(d.returnValue==='confirm'){form.dataset.confirmed='1';e.submitter.click()}},{once:true})}));document.querySelectorAll('[data-cancel-pool]').forEach(b=>b.onclick=()=>{const d=document.querySelector('#bact-cancel');d.querySelector('[name=pool_id]').value=b.dataset.cancelPool;d.showModal()});</script>
